require_once __DIR__.'/includes/auth.php';require_login();require_once __DIR__.'/includes/olympia_store.php';olympia_ensure_schema();$weekId=trim((string)($_GET['week']??''));$classId=trim((string)($_GET['class']??''));$week=olympia_week($weekId);$class=olympia_class_map()[$classId]??[];if(!$week||!olympia_can_class($classId)||!in_array($classId,olympia_week_class_ids($weekId),true)){http_response_code(403);exit('Không có quyền mở màn hình trình chiếu này.');}$logo=(string)(olympia_db()->query("SELECT setting_value FROM cds_olympia_settings WHERE setting_key='logo_url'")->fetchColumn()?:'');
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Màn hình Olympia</title><style>*{box-sizing:border-box}body{margin:0;background:#020716;color:#fff;font-family:Segoe UI,system-ui,sans-serif;overflow:hidden}.screen{height:100vh;display:flex;flex-direction:column;background:radial-gradient(circle at 50% 20%,#1476c5 0,#071b4d 48%,#020718 100%)}header{height:12vh;display:flex;align-items:center;gap:18px;padding:12px 3vw;border-bottom:3px solid #ffd42a;background:#03143cdd}.logo{width:72px;height:72px;border:2px solid #ffd42a;border-radius:50%;display:grid;place-items:center;font-size:38px;overflow:hidden}.logo img{width:100%;height:100%;object-fit:contain}.title{font-size:clamp(24px,3vw,48px);font-weight:950}.class{margin-left:auto;text-align:right;font-size:clamp(18px,2vw,30px);color:#ffd42a;font-weight:800}main{flex:1;display:grid;place-items:center;padding:4vh 5vw}.waiting{text-align:center}.waiting .mount{font-size:clamp(60px,12vw,180px)}.stage{color:#ffd42a;text-transform:uppercase;letter-spacing:.18em;font-size:clamp(18px,2vw,32px);font-weight:900}.question{text-align:center;width:100%;max-width:1500px}.qtext{font-size:clamp(38px,5.2vw,86px);line-height:1.22;font-weight:900;margin:4vh auto}.answer{display:none;background:#06352e;border:2px solid #58e49e;border-radius:18px;padding:2vh 3vw;font-size:clamp(28px,3.8vw,62px);color:#baffd5}.timer{width:120px;height:120px;border:8px solid #ffd42a;border-radius:50%;display:grid;place-items:center;margin:3vh auto;font-size:44px;font-weight:950}.summary{text-align:center}.summary h1{font-size:clamp(44px,7vw,110px);margin:2vh}.big{font-size:clamp(70px,13vw,210px);font-weight:950;color:#ffd42a}.footer{position:fixed;bottom:14px;right:20px;opacity:.55;font-size:14px}.pulse{animation:pulse 1.5s infinite}@keyframes pulse{50%{transform:scale(1.06);opacity:.75}}</style></head><body><div class="screen"><header><div class="logo"><?php if($logo):?><img src="<?=e($logo)?>" alt="Logo"><?php else:?>🏆<?php endif?></div><div><div class="title">ĐƯỜNG LÊN ĐỈNH OLYMPIA</div><div><?=e($week['title'])?></div></div><div class="class">LỚP <?=e($class['name']??'')?></div></header><main id="main"><div class="waiting"><div class="mount pulse">🏔️</div><h1>ĐANG CHỜ GIÁO VIÊN ĐIỀU KHIỂN</h1><p>Nhấn F11 để trình chiếu toàn màn hình</p></div></main><div class="footer" id="connection">Đang kết nối…</div></div><script>
const endpoint='<?=BASE_URL?>hoclieu_game_olympia_live.php?week=<?=rawurlencode($weekId)?>&class=<?=rawurlencode($classId)?>';let last='',timer=null;const main=document.getElementById('main'),conn=document.getElementById('connection');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function draw(s){let key=JSON.stringify(s);if(key===last)return;last=key;clearInterval(timer);if(!s||s.status==='waiting'||s.status==='intro'){main.innerHTML='<div class="waiting"><div class="mount pulse">🏔️</div><h1>SẴN SÀNG CHINH PHỤC ĐỈNH CAO</h1></div>';return}if(s.status==='stage_summary'||s.status==='finished'){main.innerHTML=`<div class="summary"><div class="stage">${esc(s.stage||'Kết quả')}</div><h1>${s.status==='finished'?'HOÀN THÀNH CUỘC THI':'HOÀN THÀNH CHẶNG'}</h1><div class="big">${Number(s.stage_score||s.total_score||0)}</div><p>ĐIỂM</p></div>`;return}main.innerHTML=`<div class="question"><div class="stage">${esc(s.stage)} · ${Number(s.points||0)} ĐIỂM</div><div class="qtext">${esc(s.question)}</div><div class="timer" id="clock">${Number(s.seconds||0)}</div><div class="answer" id="ans">ĐÁP ÁN: ${esc(s.answer)}</div></div>`;if(s.status==='answer'||s.status==='scoring')document.getElementById('ans').style.display='block';if(s.timer_ends_at){let tick=()=>{let left=Math.max(0,Math.ceil((Number(s.timer_ends_at)-Date.now())/1000)),el=document.getElementById('clock');if(el)el.textContent=left||'HẾT'};tick();timer=setInterval(tick,250)}}async function poll(){try{let r=await fetch(endpoint,{cache:'no-store'}),d=await r.json();if(d.ok){draw(d.state);conn.textContent='Đồng bộ · '+(d.controlled_by||'Giáo viên')}else conn.textContent=d.message}catch(e){conn.textContent='Mất kết nối, đang thử lại…'}}poll();setInterval(poll,900);
</script></body></html>
